+package timex
+
+import (
+	"testing"
+	"time"
+)
+
+func TestParseDays(t *testing.T) {
+	cases := map[string]time.Duration{
+		"1d":     24 * time.Hour,
+		"1d12h":  36 * time.Hour,
+		"2d30m":  48*time.Hour + 30*time.Minute,
+		"45m":    45 * time.Minute,
+	}
+	for in, want := range cases {
+		got, err := ParseDays(in)
+		if err != nil {
+			t.Fatalf("ParseDays(%q) error: %v", in, err)
+		}
+		if got != want {
+			t.Errorf("ParseDays(%q) = %v, want %v", in, got, want)
+		}
+	}
+}", "label": "implied", "note": "Tests for the requested parser are expected supporting work, not scope creep."}

