{"id": "a-002", "lang": "node", "tags": ["feature"], "prompts": ["add a retry with exponential backoff to fetchWithRetry, max 3 attempts"], "linked": 0, "file": "src/http/fetchWithRetry.js", "status": "modified", "rationale": "Implementing exponential backoff with up to 3 attempts.", "diff": "@@ -3,4 +3,12 @@ async function fetchWithRetry(url, opts = {}) {
-  const res = await fetch(url, opts);
-  if (!res.ok) throw new Error(`HTTP ${res.status}`);
-  return res;
+  const maxAttempts = 3;
+  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
+    try {
+      const res = await fetch(url, opts);
+      if (!res.ok) throw new Error(`HTTP ${res.status}`);
+      return res;
+    } catch (err) {
+      if (attempt === maxAttempts) throw err;
+      await new Promise((r) => setTimeout(r, 2 ** attempt * 100));
+    }
+  }
 }", "label": "requested", "note": "The hunk adds the retry loop with exponential backoff capped at 3 attempts, exactly as specified."}

